  case "$version" in ''|*[!0-9A-Za-z.+-]*) echo 'Invalid INNA_VERSION.' >&2; exit 1 ;; esac
  case "$prefix" in /*) ;; *) echo 'INNA_PREFIX must be an absolute path.' >&2; exit 1 ;; esac
