  command_matches_install() {
    case "$1" in
      "$2/bin/inna-mcp"|"$2/bin/inna-mcp "*|"$2/bin/inna-mcp-warp"|"$2/bin/inna-mcp-warp "*|\
      /bin/sh\ "$2/bin/inna-mcp"|/bin/sh\ "$2/bin/inna-mcp "*|\
      /bin/sh\ "$2/bin/inna-mcp-warp"|/bin/sh\ "$2/bin/inna-mcp-warp "*|\
      sh\ "$2/bin/inna-mcp"|sh\ "$2/bin/inna-mcp "*|\
      sh\ "$2/bin/inna-mcp-warp"|sh\ "$2/bin/inna-mcp-warp "*) return 0 ;;
    esac
    return 1
  }

  macos_executable_matches_install() {
    mapped_executables=$(lsof -a -p "$1" -d txt -Fn 2>/dev/null || true)
    case "
$mapped_executables
" in
      *"
n$2/bin/inna-mcp
"*|*"
n$2/bin/inna-mcp-warp
"*) return 0 ;;
    esac
    return 1
  }

  process_matches_install() {
    process_is_current_user "$1" || return 1
    if [ "$platform" = linux ]; then
      executable=$(readlink "/proc/$1/exe" 2>/dev/null || true)
      case "$executable" in "$2/bin/inna-mcp"|"$2/bin/inna-mcp-warp") return 0 ;; esac
    elif [ "$macos_lsof_available" = true ]; then
      macos_executable_matches_install "$1" "$2" && return 0
