  staging=
  command_tmp=
  trap 'rm -rf "$temporary"; if [ -n "$staging" ]; then rm -rf "$staging"; fi; if [ -n "$command_tmp" ]; then rm -rf "$command_tmp"; fi' 0
  trap 'exit 1' 1 2 15
  archive="inna-mcp-$version-$platform-$arch.tar.gz"
  release="https://github.com/olafurns7/family-mcp/releases/download/inna-mcp@$version"
  curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fsSL "$release/$archive" -o "$temporary/$archive"
  curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fsSL "$release/$archive.sha256" -o "$temporary/checksum"
  actual=$(cd "$temporary" && $checksum_tool "$archive")
  [ "$actual" = "$(cat "$temporary/checksum")" ] || { echo 'Release checksum verification failed; nothing was installed.' >&2; exit 1; }
  digest=${actual%% *}
  mkdir -p "$package_dir" "$prefix/bin"
  [ ! -d "$prefix/bin/inna-mcp" ] || { echo 'Install destination is a directory; nothing was replaced.' >&2; exit 1; }
