  tar -xOzf "$temporary/$archive" 'inna-mcp/bin/inna-mcp' > "$staging/bin/inna-mcp"
  chmod 755 "$staging/bin/inna-mcp"
  [ "$("$staging/bin/inna-mcp" --version </dev/null)" = "$version" ] || { echo 'Downloaded executable returned an unexpected version; previous installation kept.' >&2; exit 1; }
  for file in LICENSE README.md THIRD_PARTY_NOTICES.txt; do
    tar -xOzf "$temporary/$archive" "inna-mcp/$file" > "$staging/$file"
  done

  entrypoint=inna-mcp

  install_dir="$prefix/share/inna-mcp/$version-$digest"
  if [ -e "$install_dir" ] || [ -L "$install_dir" ]; then
    [ ! -L "$install_dir" ] && [ -d "$install_dir" ] && [ "$("$install_dir/bin/inna-mcp" --version </dev/null)" = "$version" ] || { echo 'Existing installation is invalid.' >&2; exit 1; }
    rm -rf "$staging"
  else
    mv "$staging" "$install_dir"
  fi
  staging=
  previous_install_dir=
  if [ -L "$prefix/bin/inna-mcp" ]; then
    previous_target=$(readlink "$prefix/bin/inna-mcp" 2>/dev/null || true)
    case "$previous_target" in
      "$package_dir/"*/bin/inna-mcp|"$package_dir/"*/bin/inna-mcp-warp)
        previous_install_dir=${previous_target%/bin/*}
        ;;
    esac
  fi
  command_tmp=$(mktemp -d "$prefix/bin/.inna-mcp.XXXXXX")
  ln -s "$install_dir/bin/$entrypoint" "$command_tmp/command"
  mv -f "$command_tmp/command" "$prefix/bin/inna-mcp"
  # Saved only once the scheduler matches it, so a failed change is retried by the next run.
  if [ "$renewal" = on ]; then install_renewal; else remove_renewal; fi
  printf '%s\n' "$renewal" > "$temporary/renewal"
  mv -f "$temporary/renewal" "$package_dir/renewal"
  old_processes="$temporary/old-processes"
  : > "$old_processes"
  detect_old_processes
  if [ -s "$old_processes" ]; then
    if [ "$stop_running" = true ]; then
      while IFS="$(printf '\t')" read -r process_pid candidate; do
        [ -n "$candidate" ] || continue
        process_matches_install "$process_pid" "$candidate" || continue
        kill -TERM "$process_pid" 2>/dev/null || true
      done < "$old_processes"
      waited=0
      while :; do
      running=false
      while IFS="$(printf '\t')" read -r process_pid candidate; do
          if [ -n "$candidate" ] && process_matches_install "$process_pid" "$candidate"; then running=true; fi
      done < "$old_processes"
        if [ "$running" = false ]; then break; fi
        if [ "$waited" -ge 10 ]; then break; fi
        sleep 1
        waited=$((waited + 1))
      done
      remaining=false
      while IFS="$(printf '\t')" read -r process_pid candidate; do
        if [ -z "$candidate" ]; then
          printf 'Possibly old inna-mcp process still running: PID %s (version unknown)\n' "$process_pid"
          remaining=true
        elif process_matches_install "$process_pid" "$candidate"; then
          printf 'Old inna-mcp process still running after SIGTERM: PID %s (%s)\n' "$process_pid" "$candidate"
          remaining=true
        else
          printf 'Stopped old inna-mcp process: PID %s (%s)\n' "$process_pid" "$candidate"
        fi
      done < "$old_processes"
      if [ "$remaining" = true ]; then
        printf 'Install succeeded, but old inna-mcp processes remained after SIGTERM. Restart your MCP host after stopping them.\n' >&2
        return 1
      fi
    else
      while IFS="$(printf '\t')" read -r process_pid candidate; do
        if [ -n "$candidate" ]; then
          printf 'Old inna-mcp process still running: PID %s (%s)\n' "$process_pid" "$candidate"
        else
          printf 'Possibly old inna-mcp process still running: PID %s (version unknown)\n' "$process_pid"
        fi
      done < "$old_processes"
      printf 'Restart your MCP host (Claude Desktop / Claude Code / Codex / the bot) so it starts the new version, or rerun this installer with --stop-running to send those processes SIGTERM.\n'
    fi
  fi
  printf 'Installed inna-mcp %s at %s/bin/inna-mcp\n' "$version" "$prefix"
  printf 'Use that absolute path in your MCP client. Setup: https://github.com/olafurns7/family-mcp/tree/inna-mcp@%s/packages/inna-mcp#readme\n' "$version"
  case ":${PATH:-}:" in *":$prefix/bin:"*) ;; *) printf 'For terminal use, add %s/bin to PATH.\n' "$prefix" ;; esac
}

main "$@"
